sys_script_include.script:
var LicensedSoftwareManagerAjax = Class.create();

LicensedSoftwareManagerAjax.prototype = Object.extendsObject(
    global.AbstractAjaxProcessor,
    {
        getManager: function() {
            var userId = this.getParameter('sysparm_user_id');

            if (!userId) {
                return '';
            }

            var user = new GlideRecord('sys_user');

            if (!user.get(userId)) {
                return '';
            }

            return user.getValue('manager') || '';
        },

        type: 'LicensedSoftwareManagerAjax'
    }
);
